Exception baseEx = new Exception('base message');
System.assertEquals('base message', baseEx.getMessage());
System.assertEquals('System.Exception', baseEx.getTypeName());
System.assertEquals(0, baseEx.getLineNumber());
System.assertEquals('', baseEx.getStackTraceString());
System.assertEquals(0, baseEx.getInaccessibleFields().size());
baseEx.setMessage('changed base');
System.assertEquals('changed base', baseEx.getMessage());
System.assertEquals(baseEx, baseEx.initCause(new QueryException('base cause')));
System.assertEquals('base cause', baseEx.getCause().getMessage());
